```javascript
/**
 * 获取法律服务脚本内容
 * @param {string|number} serviceId - 法律服务ID
 */
async function loadLegalContent(serviceId) {
    const url = `https://example.com/legal_services/${serviceId}.js`;

    try {
        // 发起异步 GET 请求
        const response = await fetch(url);

        // 检查 HTTP 状态码是否为 200-299 (等同于 python 的 raise_for_status)
        if (!response.ok) {
            throw new Error(`HTTP 请求失败，状态码: ${response.status}`);
        }

        // 解析响应为纯文本
        const text = await response.text();

        // 打印获取到的内容
        console.log("获取到的脚本内容：\n", text);

        // 实际应用中，您可以将内容渲染到页面上，例如：
        // document.getElementById('content-display').textContent = text;

        return text;
    } catch (error) {
        console.error(`加载外部脚本出现错误: ${error.message}`);
    }
}

// 调用示例
// loadLegalContent('divorce_law_case_01');
```

### 方案二：动态加载并执行脚本（前端常用做法）
如果您加载 `.js` 文件的目的是为了让浏览器直接执行它（例如加载特定的业务逻辑或 JSONP 数据），推荐使用动态创建 `<script>` 标签的方式。

```javascript
/**
 * 动态加载并执行法律服务脚本
 * @param {string|number} serviceId - 法律服务ID
 * @returns {Promise} 加载成功或失败的 Promise
 */
function loadAndExecuteLegalScript(serviceId) {
    return new Promise((resolve, reject) => {
        const url = `https://example.com/legal_services/${serviceId}.js`;

        // 动态创建 script 标签
        const script = document.createElement('script');
        script.src = url;
        script.type = 'text/javascript';
        script.async = true; // 异步加载，不阻塞页面渲染

        // 加载成功的回调
        script.onload = () => {
            console.log(`法律服务脚本 [${serviceId}] 加载并执行成功`);
            resolve();
        };

        // 加载失败的回调
        script.onerror = () => {
            const errorMsg = `加载外部脚本出现错误: 无法访问 ${url}`;
            console.error(errorMsg);
            reject(new Error(errorMsg));
        };

        // 将 script 标签插入到 DOM 中触发加载
        document.head.appendChild(script);
    });
}

// 调用示例
// loadAndExecuteLegalScript('divorce_law_case_01').then(() => {
//     // 脚本加载完成后的后续逻辑
// });
```

### 关键修改点说明：
1. **网络请求替换**：将 Python 的第三方库 `requests` 替换为浏览器内置的 `fetch` API（方案一）或 DOM 操作（方案二），无需额外安装依赖。
2. **异步处理 (`async/await`)**：JavaScript 的网络请求是异步的。使用 `async/await` 或 `Promise` 可以避免阻塞主线程，保证页面在加载数据时依然流畅。
3. **状态码校验**：使用 `response.ok` 替代了 Python 的 `response.raise_for_status()`，当 HTTP 状态码不在 200-299 范围内时主动抛出异常。
4. **错误捕获**：使用 `try...catch` 捕获网络断开或跨域（CORS）等请求异常，并通过 `console.error` 在浏览器控制台输出友好的错误信息。

