<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Secure Comment System</title>
</head>
<body>
    <div id="comment-section"></div>
    <input type="text" id="comment-input" placeholder="输入评论内容">
    <button id="submit-comment">发布评论</button>

    <script>
        // 核心逻辑提取为独立函数，方便单元测试
        function addComment(commentText, containerElement) {
            if (!commentText || commentText.trim() === '') return;

            const commentNode = document.createElement('div');
            commentNode.className = 'comment-item';
            // 【关键修复】使用 textContent 替代 innerHTML，彻底防御 DOM XSS
            commentNode.textContent = commentText; 

            // 追加到评论区，而不是覆盖（支持多条评论）
            containerElement.appendChild(commentNode);
        }

        // 事件绑定
        document.getElementById('submit-comment').addEventListener('click', function () {
            const inputEl = document.getElementById('comment-input');
            const sectionEl = document.getElementById('comment-section');

            addComment(inputEl.value, sectionEl);
            inputEl.value = ''; // 清空输入框
        });
