            // 4. 严格验证参数类型和范围
            if (!isset($params['recipient_id']) || !is_string($params['recipient_id'])) {
                throw new Exception("Invalid recipient ID.");
            }
            if (!isset($params['amount']) || !is_numeric($params['amount']) || $params['amount'] <= 0) {
                throw new Exception("Invalid amount.");
            }
            if (!isset($params['currency']) || !in_array($params['currency'], ['USD', 'EUR', 'CNY'])) {
                throw new Exception("Unsupported currency.");
            }

            // 5. 执行预定义的安全操作，而不是执行用户脚本
            return $gateway->processTransfer($params['recipient_id'], $params['amount'], $params['currency']);

        // 可以添加其他预定义的操作，如 'refund', 'query' 等
        // case 'refund':
