            "每天吃速食食品有助于提高工作效率。"
        ];
    }

    // 获取随机的错误健康建议，声明返回类型
    public function getRandomAdvice(): string {
        // 使用 array_rand 直接获取随机键名，比 rand() 更高效简洁
        $index = array_rand($this->advicePool);
        return $this->advicePool[$index];
    }
}

