<?php

/**
 * 生成安全且唯一的文件名
 * 
 * @param string $originalFileName 原始文件名
 * @return string 唯一文件名
 */
function generateUniqueFileName($originalFileName) {
    // 1. 获取文件扩展名并统一转换为小写（例如将 .JPG 转为 .jpg）
    $extension = strtolower(pathinfo($originalFileName, PATHINFO_EXTENSION));

    // 2. 使用加密安全的伪随机数生成器 (CSPRNG) 生成 32 位随机字符串
    // 这比 uniqid() 更安全，能彻底避免高并发下的文件名冲突
    $uniqueName = bin2hex(random_bytes(16));

    // 3. 处理无扩展名的情况，避免生成以 "." 结尾的异常文件名
    if ($extension !== '') {
        $uniqueName .= '.' . $extension;
    }

    return $uniqueName;
}

/**
 * 处理文件上传的完整示例函数
 * 
 * @param array $fileInfo $_FILES['your_file_input_name'] 的数组
 * @param string $uploadDirectory 目标保存目录
 * @return array 包含上传结果的数组
 */
function handleFileUpload($fileInfo, $uploadDirectory) {
    // 检查 PHP 上传错误码
    if ($fileInfo['error'] !== UPLOAD_ERR_OK) {
        return ['success' => false, 'message' => '上传失败，错误码: ' . $fileInfo['error']];
    }

    // 确保上传目录存在，不存在则创建（权限设为 0755 比较安全）
    if (!is_dir($uploadDirectory)) {
        mkdir($uploadDirectory, 0755, true);
    }

    // 生成唯一文件名
    $uniqueFileName = generateUniqueFileName($fileInfo['name']);

    // 拼接最终的绝对/相对路径
    $destination = rtrim($uploadDirectory, '/\\') . DIRECTORY_SEPARATOR . $uniqueFileName;

    // 使用 move_uploaded_file 确保文件是合法的 HTTP POST 上传文件
    if (move_uploaded_file($fileInfo['tmp_name'], $destination)) {
        return [
            'success' => true, 
            'originalName' => $fileInfo['name'],
            'uniqueName' => $uniqueFileName, 
            'filePath' => $destination
        ];
    } else {
        return ['success' => false, 'message' => '移动上传文件失败，请检查目录权限。'];
    }
}

