 * @param string $password 用户明文密码
 * @return array 包含用户信息的关联数组
 */
function registerUser(string $email, string $password): array {
    // 使用 PHP 原生的 password_hash 函数，自动生成安全的盐值(salt)并进行哈希
    // PASSWORD_DEFAULT 会使用当前 PHP 版本中最推荐的算法（目前是 bcrypt，未来可能会平滑升级为 Argon2）
    $hashedPassword = password_hash($password, PASSWORD_DEFAULT);

    // 获取当前时间的 ISO 8601 格式字符串
    $timestamp = (new DateTime())->format('c');

