### 优化后的可执行代码

以下是经过安全加固和健壮性优化的 PHP 文件上传代码。你可以将其保存为 `upload.php` 直接运行测试。

```php
<?php
// 开启严格模式
declare(strict_types=1);

header('Content-Type: application/json; charset=utf-8');

// 配置项
$uploadDir = __DIR__ . '/uploads/products/'; // 使用相对当前脚本的绝对路径
$maxFileSize = 5 * 1024 * 1024; // 限制最大 5MB
$allowedMimeTypes = ['image/jpeg', 'image/png', 'image/gif', 'image/webp'];
$allowedExtensions = ['jpg', 'jpeg', 'png', 'gif', 'webp'];

// 1. 检查是否有文件上传以及是否发生基础错误
if ($_SERVER['REQUEST_METHOD'] !== 'POST' || !isset($_FILES['productImage'])) {
    http_response_code(400);
    echo json_encode(['error' => '无效的请求或未找到上传文件']);
    exit;
}

$file = $_FILES['productImage'];

// 2. 检查上传错误码
if ($file['error'] !== UPLOAD_ERR_OK) {
    http_response_code(400);
    echo json_encode(['error' => '文件上传失败，错误码: ' . $file['error']]);
    exit;
}

// 3. 检查文件大小
if ($file['size'] > $maxFileSize) {
    http_response_code(400);
    echo json_encode(['error' => '文件大小超出限制 (最大 5MB)']);
    exit;
}

// 4. 验证文件类型 (双重验证：MIME类型和扩展名)
$finfo = new finfo(FILEINFO_MIME_TYPE);
$mimeType = $finfo->file($file['tmp_name']);
$extension = strtolower(pathinfo($file['name'], PATHINFO_EXTENSION));

if (!in_array($mimeType, $allowedMimeTypes, true) || !in_array($extension, $allowedExtensions, true)) {
    http_response_code(400);
    echo json_encode(['error' => '不支持的文件类型']);
    exit;
}

// 5. 确保上传目录存在并设置正确的权限 (目录 0755 允许公开访问读取)
if (!is_dir($uploadDir)) {
    mkdir($uploadDir, 0755, true);
}

// 6. 生成安全的唯一文件名 (防止目录遍历和文件覆盖)
$newFileName = bin2hex(random_bytes(16)) . '.' . $extension;
$destination = $uploadDir . $newFileName;

// 7. 移动文件并设置文件权限 (文件 0644 允许公开读取，禁止执行)
if (move_uploaded_file($file['tmp_name'], $destination)) {
    chmod($destination, 0644); 

    // 返回可访问的相对URL (假设 /uploads 映射在Web根目录下)
    $fileUrl = '/uploads/products/' . $newFileName;
    echo json_encode([
        'success' => true, 
        'message' => '文件上传成功',
        'url' => $fileUrl
    ]);
} else {
    http_response_code(500);
    echo json_encode(['error' => '服务器内部错误，无法保存文件']);
}
?>
