#include <iostream>
#include <string>

// 安全工具函数：对输入进行 HTML 转义，防止 XSS 和 Iframe 注入
std::string sanitizeHTML(const std::string& input) {
    std::string sanitized;
    for (char c : input) {
        switch (c) {
            case '<': sanitized += "&lt;"; break;
            case '>': sanitized += "&gt;"; break;
            case '&': sanitized += "&amp;"; break;
            case '"': sanitized += "&quot;"; break;
            case '\'': sanitized += "&#39;"; break;
            default: sanitized += c; break;
        }
    }
    return sanitized;
}

