```cpp
#include <iostream>
#include <thread>
#include <atomic>
#include <chrono>

using namespace std;

class EmbeddedSystem {
private:
    // 优化：使用 std::atomic 替代 volatile，保证并发环境下的原子性和内存可见性
    std::atomic<bool> interrupt_flag; 

public:
    EmbeddedSystem() : interrupt_flag(false) {}

    // 模拟硬件外部中断服务程序（ISR）
    void externalInterruptServiceRoutine() {
        if (interrupt_flag) {
            cout << "Interrupt handled, clearing interrupt flag." << endl;
            // 修复：清除中断标志，防止中断被无限重复触发
            interrupt_flag = false; 
        }
    }

    // 模拟硬件中断触发
    void triggerInterrupt() {
        interrupt_flag = true; // 设置中断标志位
    }

    // 模拟主系统任务
    void mainSystemLoop() {
        int loop_count = 0;
        // 优化：限制循环次数以便演示能够正常结束，避免死循环
        while (loop_count < 5) { 
            if (interrupt_flag) {
                externalInterruptServiceRoutine(); // 处理中断
            } else {
                cout << "Main system running..." << endl;
                this_thread::sleep_for(chrono::seconds(1));
                loop_count++;

                // 模拟在系统运行过程中再次触发中断
                if (loop_count == 2) {
                    cout << "[Hardware] Triggering interrupt again..." << endl;
                    triggerInterrupt();
                }
            }
        }
        cout << "System shutdown." << endl;
    }
};

int main() {
    EmbeddedSystem system;

    cout << "[Hardware] Initial interrupt triggered." << endl;
    // 模拟触发外部中断
    system.triggerInterrupt();

    // 启动主系统任务
    system.mainSystemLoop();

    return 0;
}
```

### 关键修改点说明

1. **修复中断死循环（核心Bug修复）**：在 `externalInterruptServiceRoutine()` 方法中补充了 `interrupt_flag = false;`。这确保了中断被处理后标志位被正确清除，主系统循环（`mainSystemLoop`）得以继续执行正常任务，而不是陷入无限处理中断的死循环。
2. **使用 `std::atomic` 替代 `volatile`**：在现代 C++ 中，`volatile` 仅防止编译器优化，**不能**保证多线程或异步中断环境下的原子性和内存屏障。将其替换为 `std::atomic<bool>` 是处理并发标志位的标准且安全的做法。
3. **优化演示逻辑**：将 `while(true)` 死循环修改为有限次数的循环（`loop_count < 5`），并在运行中途模拟了第二次中断触发。这样不仅避免了控制台无限刷屏，还能完整验证“触发 -> 处理 -> 恢复主任务 -> 再次触发”的正确闭环逻辑。

