#include <iostream>

void safeUpdateDocumentTitleCStyle(char* buffer, size_t bufferSize, const char* newTitle) {
    size_t currentLen = strlen(buffer);
    size_t remainingSpace = bufferSize - currentLen;

    // snprintf 会自动处理边界并保证以 '\0' 结尾
    snprintf(buffer + currentLen, remainingSpace, " - %s", newTitle);
}

