        std::cout << "Device " << name << " created.\n";
    }

    ~SmartHomeDevice() {
        std::cout << "Device " << name << " destroyed.\n";
    }
};

class SmartHomeController {
public:
    // 使用 shared_ptr 作为强引用，保持对象存活
    std::unordered_map<std::string, std::shared_ptr<SmartHomeDevice>> devices;
    // 使用 weak_ptr 作为弱引用，不增加引用计数，允许对象被销毁
    std::unordered_map<std::string, std::weak_ptr<SmartHomeDevice>> weak_devices;

    void add_device(const std::string& device_id, const std::string& name) {
        // std::make_shared 高效分配内存并创建对象
        auto device = std::make_shared<SmartHomeDevice>(device_id, name);
        devices[device_id] = device;       // 强引用
        weak_devices[device_id] = device;  // 弱引用
