        // erase 会移除 shared_ptr，若引用计数归零，对象将自动调用析构函数被销毁
        if (devices.erase(device_id)) {
            std::cout << "Device " << device_id << " removed.\n";
        } else {
            std::cout << "Device not found.\n";
        }
    }

