// 单元测试用例
void testDisplayQuestion() {
    Question q;
    // 包含恶意格式化字符的测试输入
    std::string maliciousInput = "What is the answer? %n %s %x";
    std::stringstream buffer;

    // 将输出流重定向到 stringstream 以便捕获输出
    q.displayQuestion(maliciousInput, buffer);

    // 断言：验证输出内容与输入完全一致，且没有因为 %n 等字符发生格式化解析或崩溃
    assert(buffer.str() == maliciousInput);

    std::cout << "[TEST PASSED] displayQuestion safely handles format string characters." << std::endl;
}

int main() {
    // 1. 执行单元测试
    testDisplayQuestion();

    // 2. 模拟实际业务运行
    std::cout << "\n--- Application Run ---" << std::endl;
    std::string userInput = "How to fix a segmentation fault?";
    Question q;
    std::cout << "Question: ";
    q.displayQuestion(userInput);
    std::cout << std::endl;

    return 0;
}
```

