package main

import (
	"html/template"
	"log"
	"net/http"
	"net/url"
)

// 使用 html/template 替代字符串拼接，自动处理上下文安全的转义
// 为 iframe 添加 sandbox 属性，限制嵌入页面的高危行为（如顶层重定向）
var iframeTmpl = template.Must(template.New("iframe").Parse(`<!DOCTYPE html>
<html>
<head>
    <title>Embedded Content</title>
</head>
<body>
    <iframe src="{{.URL}}" width="600" height="400" sandbox="allow-scripts allow-same-origin allow-forms"></iframe>
</body>
</html>`))

func iframeHandler(w http.ResponseWriter, r *http.Request) {
	iframeURL := r.URL.Query().Get("iframe_url")
	if iframeURL == "" {
		http.Error(w, "iframe URL is missing", http.StatusBadRequest)
		return
	}

	// 1. 解析并验证 URL 格式的合法性
	parsedURL, err := url.Parse(iframeURL)
	if err != nil || parsedURL.Scheme == "" || parsedURL.Host == "" {
		http.Error(w, "Invalid iframe URL format", http.StatusBadRequest)
		return
	}

	// 2. 协议白名单限制：防止 javascript:, data:, vbscript: 等恶意伪协议执行脚本
	if parsedURL.Scheme != "http" && parsedURL.Scheme != "https" {
		http.Error(w, "Only HTTP and HTTPS schemes are allowed", http.StatusBadRequest)
		return
	}

	// 3. 设置基础的安全 HTTP 响应头
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("X-Content-Type-Options", "nosniff")
	// 建议在实际生产环境中开启 CSP 白名单限制，例如：
	// w.Header().Set("Content-Security-Policy", "frame-src https://trusted-domain.com;")

	// 4. 安全渲染模板
	err = iframeTmpl.Execute(w, map[string]string{
		"URL": parsedURL.String(),
	})
	if err != nil {
		log.Printf("Template execution error: %v", err)
		http.Error(w, "Internal Server Error", http.StatusInternalServerError)
	}
}

func main() {
	http.HandleFunc("/embed", iframeHandler)

	log.Println("Server is running on http://localhost:8080 ...")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatalf("Server failed to start: %v", err)
	}
}
```

