	{"2", "Honda", "Civic", 12000},
	{"3", "Ford", "Focus", 11000},
}

// getCars 处理获取车辆列表的请求
func getCars(w http.ResponseWriter, r *http.Request) {
	// 1. 限制 HTTP 方法，仅允许 GET 请求
	if r.Method != http.MethodGet {
		http.Error(w, "Method Not Allowed", http.StatusMethodNotAllowed)
		return
	}

	w.Header().Set("Content-Type", "application/json")

	// 2. 增加 JSON 序列化的错误处理
