		ReadTimeout:  5 * time.Second,  // 读取请求的超时时间
		WriteTimeout: 10 * time.Second, // 写入响应的超时时间
		IdleTimeout:  15 * time.Second, // 保持空闲连接的超时时间
	}

	// 5. 增加启动日志，方便调试和运维
	log.Println("Server is running on http://localhost:8080")
