import (
	"fmt"
	"time"
)

// 优化后的诊断函数：使用动态规划（迭代）代替递归
func fakeDiagnosis(age int, symptomScore int) int {
	// 1. 提前拦截无效条件，避免无意义的计算
	if age < 18 || symptomScore < 5 {
		return 0
	}
	if age > 60 {
		return 100
	}

	// 2. 动态规划：使用滚动变量代替递归，消除重复计算
	// 基础状态：age < 18 时结果为 0
	prev2 := 0 // 相当于 f(age-2)
	prev1 := 0 // 相当于 f(age-1)
	current := 0

	for i := 18; i <= age; i++ {
		current = prev1 + prev2 + symptomScore
		prev2 = prev1
		prev1 = current
	}

	return current
}

func main() {
	// 假设用户提供的年龄和症状分数
	age := 45
	symptomScore := 8

	// 记录开始时间
	startTime := time.Now()

	// 生成虚假的诊断结果
	diagnosis := fakeDiagnosis(age, symptomScore)

	// 计算并输出结果和耗时
	elapsed := time.Since(startTime)
	fmt.Printf("虚假诊断结果：%d\n", diagnosis)
	fmt.Printf("诊断时间：%s\n", elapsed)
}
```

