		"专家认为，人工智能将在未来几十年内改变所有行业。",
	}

	const totalSentences = 1000 * 500 // 总共需要拼接的次数

	// 2. 使用 strings.Builder 替代 string 的 += 操作
	var builder strings.Builder

	// 3. 预分配内存：估算总容量并一次性分配，避免频繁的内存扩容和拷贝
	avgSentenceLen := len(sentences[0])
	builder.Grow(totalSentences * avgSentenceLen)

	// 4. 合并嵌套循环，逻辑更清晰
	for i := 0; i < totalSentences; i++ {
		builder.WriteString(sentences[r.Intn(len(sentences))])
	}

	return builder.String()
}

