	// 这可以防止其他系统用户窥探或篡改临时目录下的文件
	tempDir := filepath.Join(os.TempDir(), "smarthome_secure")
	if err := os.MkdirAll(tempDir, 0700); err != nil {
		fmt.Println("Error creating secure temporary directory:", err)
		return
	}

	// 2. 使用 os.CreateTemp 替代已废弃的 ioutil.TempFile
	// os.CreateTemp 默认创建的文件权限为 0600 (仅所有者可读写)，保证了文件级别的安全
	tmpfile, err := os.CreateTemp(tempDir, "device-control-*")
	if err != nil {
		fmt.Println("Error creating temporary file:", err)
		return
	}

	// 3. 修复资源泄漏和敏感信息残留：确保函数退出时先关闭、再删除临时文件
	defer os.Remove(tmpfile.Name())
	defer tmpfile.Close()

	// 写入控制指令
	_, err = tmpfile.WriteString("DeviceID: " + deviceID + ", Command: " + command)
	if err != nil {
		fmt.Println("Error writing to temporary file:", err)
		return
	}

	// 4. 确保数据真实落盘，防止系统意外崩溃导致指令丢失
	if err := tmpfile.Sync(); err != nil {
		fmt.Println("Error syncing to disk:", err)
		return
	}

	fmt.Printf("Command executed successfully. (Secure temp file used and cleaned: %s)\n", tmpfile.Name())
}

func main() {
	controlDevice("device1", "Turn On")
}
