package main

import (
	"encoding/json"
	"html"
	"log"
	"net/http"
	"time"
)

// Response 定义标准化的 JSON 返回结构
type Response struct {
	Status   string `json:"status"`
	DeviceID string `json:"device_id,omitempty"`
	Command  string `json:"command,omitempty"`
	Message  string `json:"message"`
}

func handleCommand(w http.ResponseWriter, r *http.Request) {
	// 1. 安全性：限制 HTTP 方法。控制类操作应使用 POST 而非 GET，防止参数被记录在 URL 访问日志中
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	// 解析参数 (支持 form-data 和 x-www-form-urlencoded)
	deviceID := r.FormValue("deviceID")
	command := r.FormValue("command")

	// 设置响应头为 JSON
	w.Header().Set("Content-Type", "application/json; charset=utf-8")

	if deviceID == "" || command == "" {
		w.WriteHeader(http.StatusBadRequest)
		json.NewEncoder(w).Encode(Response{
			Status:  "error",
			Message: "Missing parameters: deviceID and command are required",
		})
		return
	}

	// 2. 安全性：防御 XSS 攻击。
	// 虽然返回 JSON 天然能缓解部分 XSS，但对用户输入进行 HTML 转义是良好的深度防御习惯
	safeDeviceID := html.EscapeString(deviceID)
	safeCommand := html.EscapeString(command)

	// 模拟处理命令...

	// 返回标准化响应
	w.WriteHeader(http.StatusOK)
	json.NewEncoder(w).Encode(Response{
		Status:   "success",
		DeviceID: safeDeviceID,
		Command:  safeCommand,
		Message:  "Command received successfully",
	})
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/control", handleCommand)

	// 3. 稳定性：自定义 HTTP Server 配置
	// 默认的 http.ListenAndServe 没有超时限制，容易遭受慢速攻击 (Slowloris) 导致协程耗尽
	srv := &http.Server{
		Addr:         ":8080",
		Handler:      mux,
		ReadTimeout:  5 * time.Second,  // 读取请求头的最大时间
		WriteTimeout: 10 * time.Second, // 写入响应的最大时间
		IdleTimeout:  15 * time.Second, // 开启 Keep-Alive 时等待下一个请求的最大时间
	}

	log.Println("Secure Smart Home Server is running on port 8080...")
	if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
		log.Fatalf("Server failed to start: %v", err)
	}
}
```

### 关键修改点说明：

1. **修复 XSS (跨站脚本攻击) 漏洞**：
