package main

import (
	"errors"
	"fmt"
	"time"
)

// --- 1. 数据模型 ---

// User 代表钱包用户
type User struct {
	ID          string
	Email       string
	PhoneNumber string
	UpdatedAt   time.Time
}

// RebindRequest 换绑请求参数
type RebindRequest struct {
	UserID          string
	BindType        string // "email" 或 "phone"
	NewContact      string // 新的邮箱或手机号
	OldVerifyCode   string // 发送到旧联系方式的验证码
	NewVerifyCode   string // 发送到新联系方式的验证码
}

// --- 2. 接口定义 (用于解耦和依赖注入) ---

// UserRepository 处理数据库操作
type UserRepository interface {
	GetUserByID(id string) (*User, error)
	UpdateUserContact(id string, bindType string, newContact string) error
}

// VerificationService 处理验证码的校验
type VerificationService interface {
	VerifyCode(contact string, code string) bool
}

// --- 3. 核心业务逻辑 ---

// WalletService 钱包业务服务
type WalletService struct {
	repo        UserRepository
	verifySvc   VerificationService
}

func NewWalletService(repo UserRepository, verifySvc VerificationService) *WalletService {
	return &WalletService{repo: repo, verifySvc: verifySvc}
}

// RebindContact 执行换绑操作
func (s *WalletService) RebindContact(req RebindRequest) error {
	// 1. 参数基础校验
	if req.UserID == "" || req.NewContact == "" || req.OldVerifyCode == "" || req.NewVerifyCode == "" {
		return errors.New("所有参数均不能为空")
	}
	if req.BindType != "email" && req.BindType != "phone" {
		return errors.New("不支持的换绑类型")
	}

	// 2. 获取用户信息
	user, err := s.repo.GetUserByID(req.UserID)
	if err != nil {
		return errors.New("用户不存在")
	}

	// 3. 确定旧的联系方式
	var oldContact string
	if req.BindType == "email" {
		oldContact = user.Email
	} else {
		oldContact = user.PhoneNumber
	}

	if oldContact == "" {
		return errors.New("用户尚未绑定该类型的联系方式")
	}
	if oldContact == req.NewContact {
		return errors.New("新联系方式不能与旧联系方式相同")
	}

	// 4. 安全核心：双重验证码校验
	// 4.1 校验旧联系方式的验证码 (证明是号主本人操作)
	if !s.verifySvc.VerifyCode(oldContact, req.OldVerifyCode) {
		return errors.New("原联系方式验证码错误或已过期")
	}

	// 4.2 校验新联系方式的验证码 (证明拥有新联系方式)
	if !s.verifySvc.VerifyCode(req.NewContact, req.NewVerifyCode) {
		return errors.New("新联系方式验证码错误或已过期")
	}

	// 5. 更新数据库 (在实际应用中，这里应该是一个数据库事务)
	err = s.repo.UpdateUserContact(req.UserID, req.BindType, req.NewContact)
	if err != nil {
		return fmt.Errorf("更新绑定信息失败: %v", err)
	}

	return nil
}

