```go
package main

import (
	"fmt"
	"math/rand/v2" // 使用 Go 1.22+ 推荐的 v2 版本，无需手动 Seed
	"sync"
)

// sendNotification 模拟发送系统通知
func sendNotification(channel string, message string, wg *sync.WaitGroup) {
	defer wg.Done() // 任务完成时通知 WaitGroup
	fmt.Printf("Sending to [%s]: %s\n", channel, message)
}

// simulateLoadTest 模拟并发负载测试
func simulateLoadTest() {
	var wg sync.WaitGroup

	channels := []string{"系统告警", "用户收件箱", "审计日志"}
	messages := []string{
		"CPU 负载处于正常范围。",
		"数据库备份已成功完成。",
		"缓存清理完毕。",
		"服务健康检查通过。",
		"检测到新的常规登录。",
	}

	numTasks := 100
	wg.Add(numTasks) // 设置需要等待的 Goroutine 数量

	for i := 0; i < numTasks; i++ {
		go func() {
			// 使用 len() 动态获取切片长度，避免硬编码导致越界 panic
			channel := channels[rand.IntN(len(channels))]
			message := messages[rand.IntN(len(messages))]

			sendNotification(channel, message, &wg)
		}()
	}

	wg.Wait() // 阻塞主线程，直到所有 Goroutine 执行完毕
}

func main() {
	fmt.Println("--- 开始执行并发任务 ---")
	simulateLoadTest()
	fmt.Println("--- 所有任务执行完毕 ---")
}
```

### 关键优化点说明：

1. **使用 `sync.WaitGroup` 替代 `time.Sleep`（核心修复）**：
   * **原代码问题**：使用 `time.Sleep(5 * time.Second)` 来等待协程结束是非常糟糕的工程实践。如果任务 1 秒就跑完了，程序会白等 4 秒；如果任务需要 10 秒，程序会提前退出导致任务中断。
   * **优化后**：使用 `sync.WaitGroup` 精确追踪每一个 Goroutine 的生命周期，所有任务一结束，主程序立即退出，既安全又高效。
2. **升级随机数生成器 (`math/rand/v2`)**：
   * **原代码问题**：`rand.Seed(time.Now().UnixNano())` 在 Go 1.20 之后已被废弃。
   * **优化后**：引入 Go 1.22 的 `math/rand/v2`，它不仅性能更好，而且默认并发安全，无需手动初始化种子。
3. **消除硬编码的魔术数字**：
   * **原代码问题**：`rand.Intn(3)` 和 `rand.Intn(5)` 是硬编码

