import java.util.List;

// 优化点 1: 使用 Java Record (Java 14+) 替代传统的 POJO 类，自动生成构造函数、getter、equals 和 hashCode，使代码更简洁。
record Instruction(String itemName, List<String> steps) {
    public Instruction {
        // 优化点 2: 防御性拷贝。确保传入的 List 是不可变的，防止外部修改破坏内部状态。
        steps = List.copyOf(steps);
    }
}

class KnowledgeBase {
    // 优化点 3: 使用 final 关键字，明确表示该集合引用不会被重新赋值。
    private final List<Instruction> instructions;

    // 优化点 4: 依赖注入 (Dependency Injection)。不要在构造函数中硬编码数据，而是通过参数传入，提高类的可测试性和复用性。
    public KnowledgeBase(List<Instruction> instructions) {
        this.instructions = List.copyOf(instructions);
    }

    public void displayInstructions() {
        // 优化点 5: 使用增强的 forEach 和 Lambda 表达式，使遍历输出更加现代化和易读。
        instructions.forEach(instruction -> {
            System.out.println("制作 " + instruction.itemName() + " 的步骤：");
            instruction.steps().forEach(step -> System.out.println("- " + step));
            System.out.println(); // 添加空行增加可读性
        });
    }
}

public class GuideToMakeItems {
    public static void main(String[] args) {
        // 优化点 6: 使用 List.of() 快速创建不可变集合，替代繁琐的 add() 方法。
        List<String> cakeSteps = List.of(
            "准备面粉、鸡蛋、糖和牛奶等原料。",
            "按照特定比例混合原料并搅拌均匀。",
            "放入烤箱以180度烘焙30分钟。"
        );

        Instruction cakeInstruction = new Instruction("巧克力蛋糕", cakeSteps);

        // 将数据组装后注入到业务类中
        KnowledgeBase knowledgeBase = new KnowledgeBase(List.of(cakeInstruction));
        knowledgeBase.displayInstructions();
    }
}
```

